import { createApplication } from './bootstrap/application.js';
import { createRouteGateway } from './bootstrap/route_gateway.js';
import { getCurrentUser } from './services/auth_application_service.js';
import { pushSyncDoc, getSyncDoc } from './sync/sync_store.js';
import { getEntitlement, grantBeta, revoke } from './membership/entitlement_store.js';
import { computeFacts, buildReview, reportKey, REVIEW_MODEL_VERSION } from './review/review_service.js';
import { getReport, getLatestReport, countReportsSince, saveReport } from './review/review_store.js';
import { resolveOwner, getOverview, recordUsage, getAdminHTML } from './admin/index.js';
import { first as d1First } from './db/query.js';
import { recordConsent, hasActiveConsent, listConsentHistory, CONSENT_ACTIONS } from './legal/consent_store.js';
import { fetchDocHash, isKnownDoc } from './legal/documents.js';

// Phase 1 TASK 1.24｜Worker Entry Integration（TASK1.25 起改由 Route Gateway 分派）
//
// 每個請求都會建立一次 app = createApplication(env)（含 config/db/services/
// router），用 try/catch 包住：任何原因失敗（例如某個 binding 還沒就緒）
// 都會讓 app 是 null，不影響下面既有功能繼續運作。
//
// TASK1.25：其餘所有路由的分派交給 createRouteGateway()——依
// app.config.app.features.routeMigrationEnabled 這個 feature flag（預設
// false，見 src/config/app_config.js）決定走新架構的 Router（TASK1.21）
// 還是舊的 legacy handler（下面完全沒有變動過的 handle(r, env)）。本次
// wrangler.toml 沒有加入任何 FEATURE_ROUTE_MIGRATION_ENABLED 變數，所以
// 這個 flag 仍是關閉的。
//
// TASK1.29：正式啟用第一條 API route —— POST /auth/guest。TASK1.30
// 接著啟用 GET /auth/me、POST /auth/logout（session 使用生命週期：
// 查詢目前登入者、登出）。TASK1.31 接著啟用 POST /auth/provider/upgrade
// （訪客 → 已驗證身份 的升級入口）。TASK1.32 接著啟用 POST /auth/provider
// （provider identity 登入入口，當時刻意不接 Google OAuth callback）。
// TASK1.33 接著啟用 GET /auth/google/callback（真正接上 Google
// Authorization Code Flow 的回呼端點）。六條都刻意不透過上面的
// feature flag（那是 all-or-nothing 的機制，打開會連帶啟用 /users/:id
// 這種還沒準備好正式上線的路由），改用最小、明確的判斷式只接上這六條
// 路由：guest/provider/upgrade 解析真正的 HTTP body 成 payload，
// me/logout/upgrade 讀取真正的 Cookie 標頭（upgrade 兩者都需要——
// payload帶provider資訊、cookie用來識別「目前是哪個訪客」），
// google/callback 讀取真正的 query string（code/state）與 Cookie 標頭
// （讀取先前存放的 oauth state），交給 app.router.handle() 走完整的
// Router → Contract Validation → Controller → Application Service →
// Identity → Session → D1 流程，回傳的 Response 已經在 auth_routes.js
// 附加了真正的 Set-Cookie 標頭（guest/provider/upgrade/google-callback
// 成功時設定新session、logout 清除cookie、me 因為是純讀取所以不會有
// Set-Cookie）。google/callback 不論成功失敗一律是302 redirect（見
// auth_routes.js 的 buildGoogleCallbackResponse()），不是JSON。
//
// TASK1.35：接著啟用五個資源（exploration/food-events/emotions/
// behaviors/reports）各自的 POST（建立）/GET（查詢）共十條 User Data
// API。這十條路由額外經過 requireAuth() middleware（TASK1.27既有邏輯，
// 本次是第一次真的掛進route）驗證session，未登入直接401、不會呼叫
// controller；userId一律來自ctx.user.id（requireAuth()驗證後放入），
// 不接受payload/query指定user_id。全部委派給TASK1.15的Domain Service，
// D1操作完全不在route/controller層出現。
//
// TASK1.36：接著啟用 GET /api/dashboard——登入後首頁的資料聚合API，
// 同樣經過 requireAuth() 驗證，userId同樣一律來自ctx.user.id。
// Dashboard Controller → Dashboard Service 平行呼叫TASK1.35既有的五個
// Domain Service查詢函式，組合成單一回應，不重新實作任何查詢邏輯、
// 不修改任何既有資料表。
//
// TASK1.37：接著啟用 GET /api/profile（取得目前登入使用者基本資料）與
// PATCH /api/profile（更新display_name）。同樣經過 requireAuth() 驗證，
// userId同樣一律來自ctx.user.id。Profile Controller只會把payload裡的
// displayName欄位轉交給Profile Service，其餘任何欄位（含
// auth_provider/is_guest/status/id/created_at/last_login_at/user_id）
// 完全被忽略，不會被讀取更不會被拿去更新——不修改identity欄位、不修改
// session schema、不修改既有Domain Service。
//
// TASK1.38：接著啟用 GET /api/timeline——把五大Domain Service
// （exploration/food/emotion/behavior/report）的歷史紀錄依timestamp
// 整合成單一時間軸。同樣經過 requireAuth() 驗證，userId同樣一律來自
// ctx.user.id，這裡完全不會把query裡任何user_id欄位轉交過去。額外解析
// 真正的 query string（limit/offset），不修改任何既有資料表schema、
// 不新增AI分析邏輯（report只是原樣讀取既有內容）。
//
// 其餘所有路徑（含以上二十條路由方法不符的情況）完全不受影響，一律照舊
// 落到下面的 gateway/legacy 流程。
// TASK1.35：五個資源、共十條路徑（POST建立/GET查詢各一條）。
// TASK1.36：新增GET /api/dashboard（聚合五大domain service的登入後首頁
// API，只有GET，沒有POST）——加進同一個Set沿用下面既有的判斷式，POST
// 到這個路徑時router會因為只註冊了GET而回405，行為正確、不需要額外
// 判斷式。
const DATA_API_PATHS = new Set([
  '/api/explorations',
  '/api/food-events',
  '/api/emotions',
  '/api/behaviors',
  '/api/reports',
  '/api/dashboard',
]);

async function parseJsonBody(request) {
  try {
    const text = await request.text();
    if (!text) return {};
    return JSON.parse(text);
  } catch (e) {
    return {};
  }
}

export default {
  async fetch(request, env, ctx) {
    // Round 5: serve bundled static UI assets (real food photos, mascot, and the
    // Health Insight companion illustrations) via the Workers Static Assets
    // binding. Narrowly scoped to /ui-assets/ and /assets/health-insight/; the
    // legacy /img/ R2 route below is untouched. No SPA HTML fallback: a missing
    // asset under these prefixes returns a real 404, not the app shell.
    if (env && env.UI_ASSETS) {
      var assetPath = new URL(request.url).pathname;
      if (assetPath.startsWith('/ui-assets/') || assetPath.startsWith('/assets/health-insight/')) {
        return env.UI_ASSETS.fetch(request);
      }
    }
    let app;
    try {
      app = createApplication(env);
    } catch (e) {
      app = null;
    }

    if (app) {
      const method = request.method;
      const url = new URL(request.url);
      const pathname = url.pathname;

      if (method === 'GET' && pathname === '/auth/google/start') {
        return app.router.handle({ method, pathname, options: {} }, { db: app.db, env, services: app.services });
      }

      if (method === 'GET' && pathname === '/auth/google/callback') {
        const query = { code: url.searchParams.get('code'), state: url.searchParams.get('state') };
        const cookieHeader = request.headers.get('Cookie');
        return app.router.handle(
          { method, pathname, query, cookieHeader, options: {} },
          { db: app.db, env, services: app.services }
        );
      }

      // SECURITY (remediation 2026-09-30): a browser-supplied provider/providerId
      // pair must NEVER establish or upgrade authentication. The only trusted
      // provider login is the server-verified Google OAuth flow
      // (/auth/google/start -> /auth/google/callback). These public shortcuts are
      // disabled with an explicit failure; the router still registers the routes.
      if (method === 'POST' && (pathname === '/auth/provider' || pathname === '/auth/provider/upgrade')) {
        return new Response(
          JSON.stringify({ ok: false, error: 'direct_provider_login_disabled' }),
          { status: 403, headers: { 'Content-Type': 'application/json' } }
        );
      }

      if (method === 'POST' && pathname === '/auth/guest') {
        const payload = await parseJsonBody(request);
        return app.router.handle(
          { method, pathname, payload, options: {} },
          { db: app.db, env, services: app.services }
        );
      }

      if ((method === 'GET' && pathname === '/auth/me') || (method === 'POST' && pathname === '/auth/logout')) {
        const cookieHeader = request.headers.get('Cookie');
        return app.router.handle(
          { method, pathname, cookieHeader, options: {} },
          { db: app.db, env, services: app.services }
        );
      }

      // TASK1.35：正式啟用五個資源（exploration/food-events/emotions/
      // behaviors/reports）各自的 POST（建立）/GET（查詢）共十條 API。
      // 全部一律讀取真正的 Cookie 標頭（router 內建的 requireAuth()
      // middleware 會驗證session、解析出目前登入的user，未登入直接
      // 401短路，見 src/middleware/auth_middleware.js），POST額外解析
      // 真正的 HTTP body 成 payload，GET額外解析真正的 query string
      // （limit、behaviors多一個patternType）。userId一律由router→
      // middleware→controller這條鏈路從session取得，這裡完全不會把
      // payload/query裡任何user_id相關欄位轉交過去。
      if (DATA_API_PATHS.has(pathname)) {
        const cookieHeader = request.headers.get('Cookie');
        if (method === 'POST') {
          const payload = await parseJsonBody(request);
          return app.router.handle(
            { method, pathname, payload, cookieHeader, options: {} },
            { db: app.db, env, services: app.services }
          );
        }
        if (method === 'GET') {
          const query = { limit: url.searchParams.get('limit'), patternType: url.searchParams.get('patternType') };
          return app.router.handle(
            { method, pathname, query, cookieHeader, options: {} },
            { db: app.db, env, services: app.services }
          );
        }
      }

      // TASK1.37：正式啟用 GET /api/profile（取得目前登入使用者基本
      // 資料）與 PATCH /api/profile（更新display_name）。跟其餘API同一套
      // 安全模型：一律讀取真正的Cookie標頭交給requireAuth()驗證，
      // userId一律來自ctx.user.id，這裡完全不會把payload裡任何
      // user_id/identity/system欄位轉交過去（見
      // src/controllers/profile_controller.js的白名單設計）。
      if (pathname === '/api/profile') {
        const cookieHeader = request.headers.get('Cookie');
        if (method === 'GET') {
          return app.router.handle(
            { method, pathname, query: {}, cookieHeader, options: {} },
            { db: app.db, env, services: app.services }
          );
        }
        if (method === 'PATCH') {
          const payload = await parseJsonBody(request);
          return app.router.handle(
            { method, pathname, payload, cookieHeader, options: {} },
            { db: app.db, env, services: app.services }
          );
        }
      }

      // TASK1.38：正式啟用 GET /api/timeline（登入後使用者歷史紀錄時間
      // 軸查詢）。跟其餘API同一套安全模型：一律讀取真正的Cookie標頭交給
      // requireAuth()驗證，userId一律來自ctx.user.id，這裡完全不會把
      // query裡任何user_id欄位轉交過去（見
      // src/controllers/timeline_controller.js的獨立userId參數設計）。
      if (method === 'GET' && pathname === '/api/timeline') {
        const cookieHeader = request.headers.get('Cookie');
        const query = { limit: url.searchParams.get('limit'), offset: url.searchParams.get('offset') };
        return app.router.handle(
          { method, pathname, query, cookieHeader, options: {} },
          { db: app.db, env, services: app.services }
        );
      }

      // TASK1.116：正式啟用 GET /health-insight（Health Insight
      // Input Experience頁面）與 POST /api/health-insight（送出
      // Input Experience答案、取得Health Insight結果）——這是
      // Health Insight產品線第一個真正的application entry。跟
      // 既有二十條路由不同的是：這兩條路由刻意**不**要求登入
      // （不強制擋下未登入請求），因為Health Insight Product
      // Integration（TASK1.112）本身明確設計成不接受db/auth依賴
      // （見src/intelligence/product/health_insight_integration.js
      // 檔案頭），Input Experience只收集使用者當下填寫的輪廓
      // 答案，不查詢/不寫入任何既有使用者資料表。GET
      // /health-insight完全不需要解析任何真正的HTTP輸入，POST
      // /api/health-insight額外解析真正的HTTP body成payload（跟
      // 其餘POST路由一致的解析方式）。
      //
      // TASK1.119：POST /api/health-insight額外讀取真正的Cookie
      // 標頭——這不是要求登入，是選填的身份辨識（見
      // src/routes/health_insight_routes.js/src/identity/
      // health_insight/resolve_identity.js：沒有cookie/session
      // 無效時安全視為匿名，不會擋下request）。
      if (method === 'GET' && pathname === '/health-insight') {
        return app.router.handle({ method, pathname, options: {} }, { db: app.db, env, services: app.services });
      }

      if (method === 'POST' && pathname === '/api/health-insight') {
        const payload = await parseJsonBody(request);
        const cookieHeader = request.headers.get('Cookie');
        // 仍只傳空 options（client 無法透過 HTTP 注入權益判斷）；Phase 9 的權益
        // 強制驗證在真正付費入口 /api/review 的 server 端完成，見下方區塊。
        return app.router.handle(
          { method, pathname, payload, cookieHeader, options: {} },
          { db: app.db, env, services: app.services }
        );
      }

      // TASK1.124：正式啟用 GET /api/health-insight/history——讓
      // 使用者不需要送出新的Input Experience答案，也能單獨查看
      // 自己過去的Health Insight紀錄摘要（History Retrieval
      // Boundary，見src/history/health_insight/）。跟其餘兩條
      // Health Insight路由同一套安全模型：**不**要求登入，只是
      // 選填讀取真正的Cookie標頭做身份辨識，匿名使用者安全拿到
      // 空紀錄清單，不會被擋下。
      if (method === 'GET' && pathname === '/api/health-insight/history') {
        const cookieHeader = request.headers.get('Cookie');
        return app.router.handle(
          { method, pathname, cookieHeader, options: {} },
          { db: app.db, env, services: app.services }
        );
      }

      // TASK1.127：正式啟用 GET /app、GET /app/history、GET
      // /app/me——把Health Insight從單一功能頁面擴充成完整的
      // App Experience Layer（Home Dashboard/紀錄頁面/User
      // Center）。跟既有三條Health Insight路由同一套安全模型：
      // **不**要求登入，只是選填讀取真正的Cookie標頭做身份
      // 辨識，匿名/訪客/註冊使用者都能造訪，差別只在頁面呈現的
      // 內容。
      if (method === 'GET' && pathname === '/app') {
        const cookieHeader = request.headers.get('Cookie');
        return app.router.handle({ method, pathname, cookieHeader, options: {} }, { db: app.db, env, services: app.services });
      }

      if (method === 'GET' && pathname === '/app/history') {
        const cookieHeader = request.headers.get('Cookie');
        return app.router.handle({ method, pathname, cookieHeader, options: {} }, { db: app.db, env, services: app.services });
      }

      if (method === 'GET' && pathname === '/app/me') {
        const cookieHeader = request.headers.get('Cookie');
        return app.router.handle({ method, pathname, cookieHeader, options: {} }, { db: app.db, env, services: app.services });
      }
    }

    // SECURITY (remediation 2026-09-30): session-owned cross-device sync.
    // Ownership is the verified session user_id resolved server-side — never a
    // client-supplied code / user_id. Durable records go to D1 (per-record,
    // transactional, idempotent); QUEST live state to owner-scoped KV.
    // Unauthenticated -> 401. This intercepts before the legacy handler, so the
    // old anonymous short-code path is no longer reachable (bypass closed).
    {
      const syncPath = new URL(request.url).pathname;
      if (syncPath === '/api/sync' || syncPath === '/api/qlive') {
        if (request.method !== 'GET' && request.method !== 'POST') {
          return new Response('Method Not Allowed', { status: 405 });
        }
        const jsonHeaders = { 'Content-Type': 'application/json' };
        const cookieHeader = request.headers.get('Cookie');
        const auth = await getCurrentUser(app.db, cookieHeader, {});
        if (!auth.ok) {
          return new Response(JSON.stringify({ ok: false, error: 'not_authenticated' }), { status: 401, headers: jsonHeaders });
        }
        const ownerId = auth.userId;
        if (syncPath === '/api/sync') {
          if (request.method === 'GET') {
            const res = await getSyncDoc(app.db.raw, ownerId);
            if (!res.ok) return new Response(JSON.stringify({ ok: false, error: res.reason || 'read_failed' }), { status: 500, headers: jsonHeaders });
            try {
              const rr = ((res.doc && Array.isArray(res.doc.ins)) ? res.doc.ins.length : 0) + ((res.doc && res.doc.quest && Array.isArray(res.doc.quest.entries)) ? res.doc.quest.entries.length : 0);
              await recordUsage(app.db.raw, 'api/sync', rr, 0);
            } catch (e) {}
            return new Response(JSON.stringify({ ok: true, data: res.doc }), { headers: jsonHeaders });
          }
          const payload = await parseJsonBody(request);
          const res = await pushSyncDoc(app.db.raw, ownerId, payload);
          if (!res.ok) {
            const clientErrors = ['not_an_object', 'error_object', 'ins_not_array', 'quest_not_object', 'quest_entries_not_array', 'too_many_ins', 'too_many_quest', 'record_not_object', 'record_too_large', 'record_unserializable', 'scalars_too_large', 'scalars_unserializable'];
            const status = clientErrors.indexOf(res.reason) >= 0 ? 400 : 500;
            return new Response(JSON.stringify({ ok: false, error: res.reason || 'write_failed' }), { status, headers: jsonHeaders });
          }
          try { await recordUsage(app.db.raw, 'api/sync', 0, res.written || 0); } catch (e) {}
          return new Response(JSON.stringify({ ok: true, data: { written: res.written } }), { headers: jsonHeaders });
        }
        // /api/qlive — ephemeral QUEST live state, owner-scoped KV key
        const kv = env && env.SYNC_KV;
        if (request.method === 'GET') {
          if (!kv) return new Response(JSON.stringify({ ok: true, data: null }), { headers: jsonHeaders });
          const raw = await kv.get('qlive:u:' + ownerId);
          let parsed = null; if (raw != null) { try { parsed = JSON.parse(raw); } catch (e) { parsed = null; } }
          return new Response(JSON.stringify({ ok: true, data: parsed }), { headers: jsonHeaders });
        }
        const qpayload = await parseJsonBody(request);
        if (!qpayload || typeof qpayload !== 'object' || Array.isArray(qpayload)) {
          return new Response(JSON.stringify({ ok: false, error: 'invalid_json' }), { status: 400, headers: jsonHeaders });
        }
        const qbody = JSON.stringify(qpayload);
        if (qbody.length > 200000) return new Response(JSON.stringify({ ok: false, error: 'too_large' }), { status: 413, headers: jsonHeaders });
        if (!kv) return new Response(JSON.stringify({ ok: false, error: 'kv_unavailable' }), { status: 503, headers: jsonHeaders });
        await kv.put('qlive:u:' + ownerId, qbody, { expirationTtl: 3600 });
        return new Response(JSON.stringify({ ok: true, data: { stored: true } }), { headers: jsonHeaders });
      }
    }

    // Phase C：同意事件記錄（append-only）。/ui-assets/legal/ 靜態頁同源 POST，帶
    // session cookie；未登入 -> 401。文件雜湊由 server 從「實際服務的頁面內容」計算，
    // 綁定「同意的是哪一版文字」；文件被改過會讓舊同意失效（content_changed）。
    // 不存任何私人內容/金鑰/token（結構上無欄位）。
    {
      const consentPath = new URL(request.url).pathname;
      if (consentPath === '/api/consent' || consentPath === '/api/consent/status' || consentPath === '/api/consent/history') {
        const jsonHeaders = { 'Content-Type': 'application/json' };
        const cookieHeader = request.headers.get('Cookie');
        const auth = await getCurrentUser(app.db, cookieHeader, {});
        if (!auth.ok) {
          return new Response(JSON.stringify({ ok: false, error: 'not_authenticated' }), { status: 401, headers: jsonHeaders });
        }
        const ownerId = auth.userId;
        if (consentPath === '/api/consent/history') {
          if (request.method !== 'GET') return new Response('Method Not Allowed', { status: 405 });
          const h = await listConsentHistory(app.db.raw, ownerId);
          return new Response(JSON.stringify({ ok: !!h.ok, events: h.events || [] }), { headers: jsonHeaders });
        }
        if (consentPath === '/api/consent/status') {
          if (request.method !== 'GET') return new Response('Method Not Allowed', { status: 405 });
          const u2 = new URL(request.url);
          const docType = u2.searchParams.get('type');
          const purpose = u2.searchParams.get('purpose');
          if (!isKnownDoc(docType) || !purpose) return new Response(JSON.stringify({ ok: false, error: 'bad_params' }), { status: 400, headers: jsonHeaders });
          const dh = await fetchDocHash(env, request.url, docType);
          if (!dh.ok) return new Response(JSON.stringify({ ok: false, error: dh.reason }), { status: 503, headers: jsonHeaders });
          const st = await hasActiveConsent(app.db.raw, ownerId, purpose, { requiredVersion: dh.version, currentHash: dh.hash });
          return new Response(JSON.stringify({ ok: true, active: !!st.active, reason: st.reason || null }), { headers: jsonHeaders });
        }
        // POST /api/consent
        if (request.method !== 'POST') return new Response('Method Not Allowed', { status: 405 });
        const body = await parseJsonBody(request);
        if (!body || typeof body !== 'object' || Array.isArray(body)) return new Response(JSON.stringify({ ok: false, error: 'invalid_json' }), { status: 400, headers: jsonHeaders });
        if (!isKnownDoc(body.docType)) return new Response(JSON.stringify({ ok: false, error: 'unknown_doc' }), { status: 400, headers: jsonHeaders });
        if (CONSENT_ACTIONS.indexOf(body.action) < 0) return new Response(JSON.stringify({ ok: false, error: 'bad_action' }), { status: 400, headers: jsonHeaders });
        if (!body.purpose || typeof body.purpose !== 'string') return new Response(JSON.stringify({ ok: false, error: 'missing_purpose' }), { status: 400, headers: jsonHeaders });
        const dh = await fetchDocHash(env, request.url, body.docType);
        if (!dh.ok) return new Response(JSON.stringify({ ok: false, error: dh.reason }), { status: 503, headers: jsonHeaders });
        const rec = await recordConsent(app.db.raw, {
          userId: ownerId, purpose: String(body.purpose).slice(0, 64), docType: body.docType, docVersion: dh.version,
          docContentSha256: dh.hash, action: body.action,
          sourceScreen: (typeof body.sourceScreen === 'string' && body.sourceScreen) ? body.sourceScreen.slice(0, 64) : 'legal_page',
          orderId: (typeof body.orderId === 'string' && body.orderId) ? body.orderId.slice(0, 64) : null,
        });
        if (!rec.ok) return new Response(JSON.stringify({ ok: false, error: rec.reason }), { status: 400, headers: jsonHeaders });
        return new Response(JSON.stringify({ ok: true, eventId: rec.eventId }), { headers: jsonHeaders });
      }
    }

    // Phase 9：7 日飲食行為回顧（Premium 第一個付費功能）。
    // 權益一律 server 端驗證（getEntitlement），不信前端宣稱的 tier。
    // GET = 重看最近一份（不扣額度）；POST = 產生（確定性；idempotent by key；
    // beta 每帳號上限 REVIEW_BETA_ALLOWANCE）。Gemini 本輪關閉，走純確定性。
    {
      const reviewPath = new URL(request.url).pathname;
      if (reviewPath === '/api/review') {
        const jsonHeaders = { 'Content-Type': 'application/json' };
        if (request.method !== 'GET' && request.method !== 'POST') {
          return new Response('Method Not Allowed', { status: 405 });
        }
        const cookieHeader = request.headers.get('Cookie');
        const auth = await getCurrentUser(app.db, cookieHeader, {});
        if (!auth.ok) {
          return new Response(JSON.stringify({ ok: false, error: 'not_authenticated' }), { status: 401, headers: jsonHeaders });
        }
        const ownerId = auth.userId;
        const ent = await getEntitlement(app.db.raw, ownerId);
        if (ent.tier === 'unknown') {
          // 權益查詢暫時失敗 → 不顯示購買提示、不永久降級
          return new Response(JSON.stringify({ ok: false, error: 'entitlement_unavailable' }), { status: 503, headers: jsonHeaders });
        }
        if (ent.tier !== 'premium') {
          return new Response(JSON.stringify({ ok: false, error: 'premium_required', tier: ent.tier }), { status: 403, headers: jsonHeaders });
        }

        const REVIEW_BETA_ALLOWANCE = 2;
        const sync = await getSyncDoc(app.db.raw, ownerId);
        const doc = (sync && sync.ok) ? sync.doc : { ins: [] };
        const facts = computeFacts(doc, Date.now());
        const review = buildReview(facts);
        const key = reportKey(facts, REVIEW_MODEL_VERSION);

        if (request.method === 'GET') {
          // 先看這份是否已產生過（重看，不扣額度）
          const cached = await getReport(app.db.raw, ownerId, key);
          if (cached.ok && cached.report) {
            return new Response(JSON.stringify({ ok: true, data: { review: cached.report.payload, cached: true, generatedAt: cached.report.createdAt } }), { headers: jsonHeaders });
          }
          // 否則回最近一份（若有）供重看，並附「目前視窗可否產生」
          const latest = await getLatestReport(app.db.raw, ownerId);
          const used = await countReportsSince(app.db.raw, ownerId, null);
          return new Response(JSON.stringify({ ok: true, data: {
            review: (latest.ok && latest.report) ? latest.report.payload : null,
            cached: !!(latest.ok && latest.report),
            available: !!(latest.ok && latest.report),
            canGenerate: review.kind === 'personalized' && used.count < REVIEW_BETA_ALLOWANCE,
            dataLimitation: review.kind === 'basic',
            summaryPreview: review.summary,
            quota: { used: used.count, limit: REVIEW_BETA_ALLOWANCE }
          } }), { headers: jsonHeaders });
        }

        // POST = 產生
        if (review.kind === 'basic') {
          // 資料不足：回基本摘要 + 資料限制，不扣額度、不寫入（基本摘要不是 premium 產生）
          return new Response(JSON.stringify({ ok: true, data: { review, generated: false, dataLimitation: true } }), { headers: jsonHeaders });
        }
        // 同資料+視窗已產生過 → 回快取（idempotent，不扣額度）
        const existing = await getReport(app.db.raw, ownerId, key);
        if (existing.ok && existing.report) {
          const usedNow = await countReportsSince(app.db.raw, ownerId, null);
          return new Response(JSON.stringify({ ok: true, data: { review: existing.report.payload, generated: false, cached: true, generatedAt: existing.report.createdAt, quota: { used: usedNow.count, limit: REVIEW_BETA_ALLOWANCE } } }), { headers: jsonHeaders });
        }
        // 配額檢查（beta：每帳號 distinct 報告數上限）
        const used = await countReportsSince(app.db.raw, ownerId, null);
        if (used.count >= REVIEW_BETA_ALLOWANCE) {
          return new Response(JSON.stringify({ ok: false, error: 'quota_exhausted', quota: { used: used.count, limit: REVIEW_BETA_ALLOWANCE } }), { status: 429, headers: jsonHeaders });
        }
        // 產生並寫入（Gemini 關閉 → 純確定性）。idempotent：ON CONFLICT DO NOTHING。
        const saved = await saveReport(app.db.raw, ownerId, key, {
          windowStart: facts.windowStartKey, windowEnd: facts.windowEndKey,
          dataVersion: String(facts.recordCount) + ':' + String(facts.latestTs), modelVersion: REVIEW_MODEL_VERSION
        }, review);
        if (!saved.ok) {
          return new Response(JSON.stringify({ ok: false, error: saved.reason || 'save_failed' }), { status: 500, headers: jsonHeaders });
        }
        const after = await countReportsSince(app.db.raw, ownerId, null);
        try { await recordUsage(app.db.raw, 'api/review', facts.recordCount || 0, saved.inserted ? 1 : 0); } catch (e) {}
        return new Response(JSON.stringify({ ok: true, data: { review, generated: saved.inserted, quota: { used: after.count, limit: REVIEW_BETA_ALLOWANCE } } }), { headers: jsonHeaders });
      }
    }

    // Phase 9（後台 A 階段）：擁有者專用後台。只有 env.ADMIN_GOOGLE_SUB 對應的
    // Google 帳號（已驗證 session 的 auth_provider_id）能進。頁面與 API 都在 server
    // 端驗證擁有者。只讀聚合人數/會員/稽核/用量，沒有任何飲食明細 API。
    {
      const adminPath = new URL(request.url).pathname;
      if (adminPath === '/admin' || adminPath.indexOf('/api/admin/') === 0) {
        const jsonHeaders = { 'Content-Type': 'application/json' };
        const cookieHeader = request.headers.get('Cookie');
        const own = await resolveOwner(app.db, app.db.raw, cookieHeader, env);
        // whoami：永遠回 200，只告訴前端「要不要顯示管理後台入口」。
        // 真正的後台存取仍由下方 owner 閘門把關，前端無法靠這個繞過。
        if (adminPath === '/api/admin/whoami' && request.method === 'GET') {
          return new Response(JSON.stringify({ ok: true, owner: !!own.owner }), { headers: jsonHeaders });
        }
        if (adminPath === '/admin' && request.method === 'GET') {
          if (!own.owner) {
            return new Response('403 — 此頁僅限擁有者', { status: 403, headers: { 'Content-Type': 'text/plain; charset=utf-8' } });
          }
          return new Response(getAdminHTML(), { headers: { 'Content-Type': 'text/html; charset=utf-8' } });
        }
        if (!own.authenticated) return new Response(JSON.stringify({ ok: false, error: 'not_authenticated' }), { status: 401, headers: jsonHeaders });
        if (!own.owner) return new Response(JSON.stringify({ ok: false, error: 'forbidden' }), { status: 403, headers: jsonHeaders });
        if (request.method === 'POST') {
          // Origin 檢查（SameSite=Lax 已擋跨站 POST，這是縱深防禦）。
          // host 由 request.url 推導（Host 標頭不一定存在）。
          const origin = request.headers.get('Origin');
          const host = new URL(request.url).host;
          if (origin && host && origin.indexOf('://' + host) === -1) {
            return new Response(JSON.stringify({ ok: false, error: 'bad_origin' }), { status: 403, headers: jsonHeaders });
          }
        }
        if (adminPath === '/api/admin/overview' && request.method === 'GET') {
          const ov = await getOverview(app.db.raw, {});
          return new Response(JSON.stringify(ov), { headers: jsonHeaders });
        }
        if ((adminPath === '/api/admin/grant' || adminPath === '/api/admin/revoke') && request.method === 'POST') {
          const body = await parseJsonBody(request);
          const who = body && typeof body.who === 'string' ? body.who.trim() : '';
          if (!who) return new Response(JSON.stringify({ ok: false, error: 'missing_who' }), { status: 400, headers: jsonHeaders });
          // who 可為 user id，或 Google sub（auth_provider_id）。users 表無 email。
          let targetId = null;
          const byId = await d1First(app.db.raw, 'SELECT id FROM users WHERE id = ?', [who]);
          if (byId.ok && byId.row) targetId = byId.row.id;
          if (!targetId) {
            const bySub = await d1First(app.db.raw, "SELECT id FROM users WHERE auth_provider = 'google' AND auth_provider_id = ?", [who]);
            if (bySub.ok && bySub.row) targetId = bySub.row.id;
          }
          if (!targetId) return new Response(JSON.stringify({ ok: false, error: 'user_not_found' }), { status: 404, headers: jsonHeaders });
          if (adminPath === '/api/admin/grant') {
            const days = (body && Number(body.days) > 0) ? Number(body.days) : 14;
            const tier = (body && typeof body.tier === 'string' && body.tier) ? body.tier : 'app';
            const r = await grantBeta(app.db.raw, targetId, days, 'admin_ui', 'owner:' + own.userId, tier);
            if (!r.ok) return new Response(JSON.stringify({ ok: false, error: r.reason || 'grant_failed' }), { status: 500, headers: jsonHeaders });
            return new Response(JSON.stringify({ ok: true, validUntil: r.validUntil }), { headers: jsonHeaders });
          }
          const r = await revoke(app.db.raw, targetId, 'owner:' + own.userId);
          if (!r.ok) return new Response(JSON.stringify({ ok: false, error: r.reason || 'revoke_failed' }), { status: 500, headers: jsonHeaders });
          return new Response(JSON.stringify({ ok: true }), { headers: jsonHeaders });
        }
        return new Response(JSON.stringify({ ok: false, error: 'not_found' }), { status: 404, headers: jsonHeaders });
      }
    }

    const gateway = createRouteGateway({ app, legacyHandler: handle });
    return gateway.handle(request, env);
  }
};

async function handle(r,env){
  var p=new URL(r.url).pathname;
  if(p==='/manifest.json')return new Response(getManifest(),{headers:{'Content-Type':'application/manifest+json','Cache-Control':'public,max-age=86400'}});
  if(p==='/apple-touch-icon.png'||p==='/apple-touch-icon-precomposed.png'){
    var b=atob(ICON_PNG);var u=new Uint8Array(b.length);
    for(var i=0;i<b.length;i++)u[i]=b.charCodeAt(i);
    return new Response(u,{headers:{'Content-Type':'image/png','Cache-Control':'public,max-age=86400'}});
  }
  if(p==='/icon.svg')return new Response(getIconSVG(),{headers:{'Content-Type':'image/svg+xml','Cache-Control':'public,max-age=86400'}});
  if(p.indexOf('/img/')===0){
    var imgKey=p.slice(5);
    if(!/^[a-z0-9_\-/.]{1,200}$/.test(imgKey)){
      return new Response('Not Found',{status:404});
    }
    try{
      var imgObj=(env&&typeof env.DIET_COACH_IMAGES!=='undefined')?await env.DIET_COACH_IMAGES.get(imgKey):null;
      if(!imgObj){
        return new Response('Not Found',{status:404});
      }
      return new Response(imgObj.body,{headers:{'Content-Type':'image/jpeg','Cache-Control':'public,max-age=604800,immutable'}});
    }catch(imgErr){
      return new Response('Not Found',{status:404});
    }
  }
  if(p==='/api/sync'){
    // SUPERSEDED (remediation 2026-09-30): anonymous short-code sync is removed.
    // The authenticated, session-owned handler in fetch() intercepts /api/sync
    // before this legacy handler runs, so this block is unreachable and kept only
    // for structural stability. Fail closed if ever reached — no code-based access.
    return new Response(JSON.stringify({ok:false,error:'legacy_sync_disabled'}),{status:410,headers:{'Content-Type':'application/json'}});
  }
  if(p==='/api/qlive'){
    // SUPERSEDED (remediation 2026-09-30): see /api/sync above. Fail closed.
    return new Response(JSON.stringify({ok:false,error:'legacy_qlive_disabled'}),{status:410,headers:{'Content-Type':'application/json'}});
  }
  return new Response(getHTML(),{headers:{'Content-Type':'text/html;charset=utf-8','Cache-Control':'no-store'}});
}
var ICON_PNG='';
function getManifest(){return '{"name":"\\u98f2\\u98df\\u4e3b\\u5834\\u79c0","short_name":"\\u98f2\\u98df\\u4e3b\\u5834\\u79c0","description":"\\u4e86\\u89e3\\u81ea\\u5df1\\uff0c\\u624d\\u80fd\\u771f\\u6b63\\u5403\\u597d","icons":[{"src":"/apple-touch-icon.png","sizes":"180x180","type":"image/png"}],"start_url":"/","display":"standalone","background_color":"#C8794A","theme_color":"#C8794A","orientation":"portrait-primary"}';}
function getIconSVG(){return '<svg viewBox="0 0 160 160" xmlns="http://www.w3.org/2000/svg"><defs><clipPath id="ic"><ellipse cx="80" cy="72" rx="54" ry="19"/></clipPath></defs><rect width="160" height="160" rx="36" fill="#C8794A"/><ellipse cx="80" cy="136" rx="46" ry="8" fill="rgba(0,0,0,.15)"/><path d="M 26,72 C 18,106 38,138 80,140 C 122,138 142,106 134,72" fill="#F6E8D4"/><path d="M 30,74 C 24,106 42,134 80,136 C 118,134 136,106 130,74" fill="#E4BF9C"/><g clip-path="url(#ic)"><rect x="26" y="53" width="54" height="38" fill="#3D7A34"/><path d="M 34,58 C 30,52 38,46 44,52 C 40,54 38,58 34,58 Z" fill="#2A5E24"/><path d="M 52,55 C 48,49 56,43 62,49 C 58,51 56,55 52,55 Z" fill="#4A8A40"/><path d="M 38,70 C 34,64 42,58 48,64 C 44,66 42,70 38,70 Z" fill="#2A5E24"/><rect x="80" y="53" width="54" height="19" fill="#C03818"/><ellipse cx="95" cy="61" rx="8" ry="6" fill="#9C2C10"/><ellipse cx="110" cy="58" rx="6" ry="5" fill="#D84830"/><ellipse cx="124" cy="61" rx="6" ry="5" fill="#B03020"/><rect x="80" y="72" width="54" height="19" fill="#FFF8BE"/><ellipse cx="95" cy="81" rx="9" ry="6" fill="#FFEF90"/><ellipse cx="113" cy="79" rx="7" ry="5" fill="#FFF4C4"/><rect x="78" y="53" width="4" height="38" fill="rgba(255,255,255,.9)"/><rect x="80" y="70" width="54" height="4" fill="rgba(255,255,255,.9)"/></g><ellipse cx="80" cy="72" rx="54" ry="19" fill="#F9F0E4"/><ellipse cx="80" cy="69" rx="50" ry="15" fill="rgba(255,252,248,.55)"/><path d="M 34,76 A 54,19 0 0 0 126,76" fill="none" stroke="#C8A078" stroke-width="2.5"/><path d="M 56,54 C 52,45 56,37 52,28" fill="none" stroke="rgba(255,255,255,.65)" stroke-width="2.5" stroke-linecap="round"/><path d="M 80,51 C 76,42 80,34 76,25" fill="none" stroke="rgba(255,255,255,.52)" stroke-width="2.5" stroke-linecap="round"/><path d="M 104,54 C 100,45 104,37 100,28" fill="none" stroke="rgba(255,255,255,.38)" stroke-width="2" stroke-linecap="round"/></svg>';}
