  '.ob-btn{margin:0 24px 48px;padding:18px;background-color:var(--pk);background-image:var(--grain);background-size:90px;background-blend-mode:multiply;color:#fff;border:2.5px solid #9A582D;border-radius:var(--hd2);font-size:19px;font-weight:700;letter-spacing:1px;cursor:pointer;transition:transform .1s,box-shadow .2s;box-shadow:0 5px 0 rgba(154,88,45,.7);}',
  '.ob-btn:active{transform:translateY(4px);box-shadow:0 1px 0 rgba(154,88,45,.7);}',
  '#sh{overflow-y:auto;padding-bottom:80px;}',
