  'var QLIVE_PREF_KEY="quest_live_pref";',
  'var QLIVE_ON=false;var QLIVE_TS=0;var QLIVE_POLL=null;var QLIVE_PUSH_T=null;',
  'function qliveGetPref(){try{return localStorage.getItem(QLIVE_PREF_KEY)==="1";}catch(e){return false;}}',
  'function qliveSetPref(v){try{localStorage.setItem(QLIVE_PREF_KEY,v?"1":"0");}catch(e){}}',
  'function qliveSnapshot(){',
  '  var ta=document.getElementById("qst-note");',
  '  return{mode:QST.mode,phase:QST.phase,stepCats:QST.stepCats,stepIdx:QST.stepIdx,confirmed:QST.confirmed,current:QST.current,cards:QST.cards,prompts:QST.prompts,insight:QST.insight,savedCarry:QST.savedCarry,note:ta?ta.value:""};',
  '}',
  'function qlivePush(){',
