  'ICONS.f_fruit=\'<svg viewBox="0 0 32 32" fill="none" stroke="#7A5138" stroke-width="2" stroke-linejoin="round" stroke-linecap="round"><path d="M16 10 c-6 -4 -12 2 -10 9 c1.5 6 6 9 10 9 c4 0 8.5 -3 10 -9 c2 -7 -4 -13 -10 -9z" fill="#D98F82" stroke="#A84E42"/><path d="M16 10 q1 -5 5 -6" stroke="#527040" stroke-width="2"/><path d="M17 6 q4 -2 5 1 q-4 2 -5 -1z" fill="#8FAE7A" stroke="#527040"/></svg>\';',
