  'function idqCardSVG(t){',
  '  var a=ID_ART[t.key];',
  '  var f=\'PingFang TC, Noto Sans TC, Microsoft JhengHei, sans-serif\';',
  '  var svg=\'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1080 1080" width="1080" height="1080">\';',
  '  svg+=\'<defs><linearGradient id="idqg" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="\'+a.g1+\'"/><stop offset="1" stop-color="\'+a.g2+\'"/></linearGradient></defs>\';',
  '  svg+=\'<rect width="1080" height="1080" fill="url(#idqg)"/>\';',
  '  svg+=\'<circle cx="110" cy="120" r="95" fill="rgba(255,255,255,.08)"/><circle cx="970" cy="950" r="150" fill="rgba(255,255,255,.08)"/>\';',
  '  svg+=\'<text x="540" y="130" font-size="32" font-weight="700" fill="rgba(255,255,255,.85)" text-anchor="middle" font-family="\'+f+\'">飲食身份認同小測驗</text>\';',
  '  svg+=\'<g transform="translate(340,270) scale(2)">\'+a.art+\'</g>\';',
  '  svg+=\'<text x="540" y="740" font-size="62" font-weight="800" fill="#fff" text-anchor="middle" font-family="\'+f+\'">\'+t.title+\'</text>\';',
  '  svg+=\'<text x="540" y="820" font-size="40" font-weight="700" fill="rgba(255,255,255,.95)" text-anchor="middle" font-family="\'+f+\'">\'+a.l1+\'</text>\';',
  '  svg+=\'<text x="540" y="875" font-size="40" font-weight="700" fill="rgba(255,255,255,.95)" text-anchor="middle" font-family="\'+f+\'">\'+a.l2+\'</text>\';',
  '  svg+=\'<rect x="390" y="945" width="300" height="2" fill="rgba(255,255,255,.4)"/>\';',
  '  svg+=\'<text x="540" y="1000" font-size="26" fill="rgba(255,255,255,.78)" text-anchor="middle" font-family="\'+f+\'">飲食主場秀・飲食身份認同小測驗</text>\';',
  '  svg+=\'</svg>\';',
  '  return svg;',
  '}',
  'function shareIdCard(t){',
  '  var svg=idqCardSVG(t);',
  '  var svgBlob=new Blob([svg],{type:"image/svg+xml;charset=utf-8"});',
  '  var url=URL.createObjectURL(svgBlob);',
  '  var img=new Image();',
  '  img.onload=function(){',
  '    var canvas=document.createElement("canvas");canvas.width=1080;canvas.height=1080;',
  '    var ctx=canvas.getContext("2d");ctx.drawImage(img,0,0,1080,1080);',
  '    URL.revokeObjectURL(url);',
  '    canvas.toBlob(function(blob){',
  '      var fname="diet-identity-"+t.key+".png";',
  '      var file=new File([blob],fname,{type:"image/png"});',
  '      if(navigator.share&&navigator.canShare&&navigator.canShare({files:[file]})){',
  '        navigator.share({files:[file],text:t.line}).catch(function(e){});',
  '        return;',
  '      }',
  '      var a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download=fname;',
  '      document.body.appendChild(a);a.click();',
  '      setTimeout(function(){document.body.removeChild(a);URL.revokeObjectURL(a.href);},1000);',
  '    },"image/png");',
  '  };',
  '  img.src=url;',
  '}',
  'var IDQI=-1;var IDQ_ANS=[];',
  'function idTypeByKey(k){for(var i=0;i<ID_TYPES.length;i++)if(ID_TYPES[i].key===k)return ID_TYPES[i];return null;}',
  'function idqCompute(){',
  '  var counts=[0,0,0,0,0],i;',
  '  for(i=0;i<IDQ_ANS.length;i++)counts[IDQ_ANS[i]]++;',
  '  var best=0;',
  '  for(i=1;i<counts.length;i++)if(counts[i]>counts[best])best=i;',
  '  return ID_TYPES[best];',
  '}',
  'function showIdentityQuiz(){IDQI=-1;IDQ_ANS=[];showScreen("sidq");renderIdq();}',
  'function showIdentityResult(){if(!ld().identity){showIdentityQuiz();return;}IDQI=ID_QUESTIONS.length;showScreen("sidq");renderIdq();}',
  'function idqAnswer(idx){',
  '  IDQ_ANS.push(idx);IDQI++;',
  '  if(IDQI>=ID_QUESTIONS.length){',
  '    var t=idqCompute();var data=ld();data.identity={key:t.key,ts:Date.now()};sd(data);',
  '  }',
  '  renderIdq();',
  '}',
  'function renderIdq(){',
  '  var body=document.getElementById("idq-body");body.innerHTML="";',
  '  var skipBtn=document.getElementById("idq-skip-btn");',
  '  if(IDQI<0){',
  '    tx("idq-prog","");skipBtn.textContent="略過";skipBtn.style.visibility="visible";skipBtn.onclick=goHome;',
  '    body.appendChild(icoDiv("idq-emoji","sprout",46));',
  '    body.appendChild(mkEl("div","idq-intro-title","飲食身份認同小測驗"));',
  '    body.appendChild(mkEl("div","idq-intro-sub","5 個小問題，看看你現在最像哪一種飲食身份，幫助你用更貼近自己的方式繼續調整。"));',
  '    var startBtn=mkEl("button","idq-btn","開始測驗");',
  '    startBtn.onclick=function(){IDQI=0;renderIdq();};',
  '    body.appendChild(startBtn);',
  '    return;',
  '  }',
  '  if(IDQI<ID_QUESTIONS.length){',
  '    tx("idq-prog","第 "+(IDQI+1)+" / "+ID_QUESTIONS.length+" 題");',
  '    skipBtn.textContent="略過";skipBtn.style.visibility="visible";skipBtn.onclick=goHome;',
  '    var qd=ID_QUESTIONS[IDQI];',
  '    body.appendChild(mkEl("div","idq-q",qd.q));',
  '    qd.opts.forEach(function(label,i){',
  '      var btn=mkEl("button","idq-opt",label);',
  '      btn.onclick=function(){idqAnswer(i);};',
  '      body.appendChild(btn);',
  '    });',
  '    return;',
  '  }',
  '  tx("idq-prog","");skipBtn.style.visibility="hidden";',
  '  var t=idTypeByKey(ld().identity.key);',
  '  body.appendChild(mkEl("div","idq-result-badge",t.icon));',
  '  body.appendChild(mkEl("div","idq-result-title",t.title));',
  '  body.appendChild(mkEl("div","idq-result-line",t.line));',
  '  var shareWrap=mkEl("div","idq-share-wrap");',
  '  shareWrap.innerHTML=idqCardSVG(t);',
  '  body.appendChild(shareWrap);',
  '  var shareBtn=mkEl("button","idq-btn","下載／分享我的身份卡");',
  '  shareBtn.onclick=function(){shareIdCard(t);};',
  '  body.appendChild(shareBtn);',
  '  var card=mkEl("div","res-card");',
  '  card.appendChild(mkEl("div","rc-lbl","關於你"));',
  '  card.appendChild(mkEl("div","dim-body",t.desc));',
  '  card.appendChild(mkEl("div","dim-tip",t.strength));',
  '  card.appendChild(mkEl("div","dim-tip",t.tip));',
  '  body.appendChild(card);',
  '  var idqST=t.icon+" "+t.title+"\\n"+t.line+"\\n\\n"+t.desc+"\\n\\n "+t.strength+"\\n"+t.tip+"\\n\\n— 飲食行為教練 App";',
  '  addShareBar(body,{text:idqST,emoji:t.icon,title:"飲食身份："+t.title,sections:[{label:t.line},{text:t.desc},{label:"你的優勢"},{text:t.strength},{text:t.tip}]});',
  '  var homeBtn=mkEl("button","idq-btn","回首頁");',
  '  homeBtn.onclick=goHome;',
  '  body.appendChild(homeBtn);',
  '  var retakeBtn=mkEl("button","idq-btn sec","重新測驗");',
  '  retakeBtn.onclick=showIdentityQuiz;',
  '  body.appendChild(retakeBtn);',
  '}',
  'function renderIdentityCard(){',
  '  var el=document.getElementById("idcard");if(!el)return;',
  '  el.innerHTML="";',
  '  var data=ld();var t=data.identity?idTypeByKey(data.identity.key):null;',
  '  if(t){',
  '    var card=mkEl("div","idc-badge");card.onclick=showIdentityResult;',
  '    var idem=mkEl("div","idc-emoji");var _is=icoSpan("sprout",30);if(_is)idem.appendChild(_is);card.appendChild(idem);',
  '    var info=mkEl("div");',
  '    info.appendChild(mkEl("div","idc-title",t.title+"・"+t.line));',
  '    info.appendChild(mkEl("div","idc-line","點一下查看／分享身份卡"));',
  '    card.appendChild(info);',
  '    el.appendChild(card);',
  '  }else{',
  '    var cta=mkEl("div","idc-cta");cta.onclick=showIdentityQuiz;',
  '    cta.appendChild(mkEl("div","idc-cta-txt","還沒做過飲食身份測驗"));',
  '    cta.appendChild(mkEl("div","idc-cta-btn","開始測驗"));',
  '    el.appendChild(cta);',
  '  }',
  '  var rvcta=mkEl("div","idc-cta");rvcta.onclick=showReviewScreen;',
  '  rvcta.appendChild(mkEl("div","idc-cta-txt","7 日飲食回顧 · 會員專屬"));',
  '  rvcta.appendChild(mkEl("div","idc-cta-btn","查看"));',
  '  el.appendChild(rvcta);',
  '  adminEntryCheck(el);',
  '}',
  'function adminEntryCheck(el){',
  '  if(!el)return;',
  '  fetch("/api/admin/whoami",{headers:{"Accept":"application/json"}}).then(function(r){return r.json();}).then(function(j){',
  '    if(j&&j.ok&&j.owner){',
  '      if(document.getElementById("owner-admin-cta"))return;',
  '      var a=mkEl("div","idc-cta");a.id="owner-admin-cta";a.onclick=function(){window.open("/admin","_blank");};',
  '      a.appendChild(mkEl("div","idc-cta-txt","管理後台（僅限你本人）"));',
  '      a.appendChild(mkEl("div","idc-cta-btn","開啟 →"));',
  '      el.insertBefore(a,el.firstChild);',
  '    }',
  '  }).catch(function(){});',
  '}',
