  '  }',
  '  var moodArr=[];for(var mk in st.moodCounts){moodArr.push({key:mk,count:st.moodCounts[mk]});}',
  '  moodArr.sort(function(a,b){return b.count-a.count;});',
  '  if(moodArr.length>0){',
  '    card.appendChild(mkEl("div","rc-lbl","常見情緒狀態"));',
  '    var mrow=mkEl("div","ml-stat");',
  '    moodArr.slice(0,3).forEach(function(m){',
  '      var mo=divnGetMoodObj(m.key);if(!mo)return;',
  '      var it=mkEl("div","ml-stat-i");',
  '      it.appendChild(mkEl("div","ml-stat-n",mo.emoji));',
  '      it.appendChild(mkEl("div","ml-stat-l",mo.label+" ×"+m.count));',
