  '  var tArr=[];var fArr=[];',
  '  for(var tk in st.tasteCounts){var td=DIVN_TASTES[tk];var fd=DIVN_FEELS[tk];if(td)tArr.push({key:tk,count:st.tasteCounts[tk],label:td.emoji+" "+td.label});else if(fd)fArr.push({key:tk,count:st.tasteCounts[tk],label:fd.label});else tArr.push({key:tk,count:st.tasteCounts[tk],label:tk});}',
  '  tArr.sort(function(a,b){return b.count-a.count;});',
  '  fArr.sort(function(a,b){return b.count-a.count;});',
  '  if(tArr.length>0){',
  '    card.appendChild(mkEl("div","rc-lbl","偏好口味"));',
  '    var trow=mkEl("div","ml-stat");',
  '    tArr.slice(0,4).forEach(function(ti){',
  '      var it=mkEl("div","ml-stat-i");',
  '      it.appendChild(mkEl("div","ml-stat-l",ti.label+" ×"+ti.count));',
  '      trow.appendChild(it);',
  '    });',
  '    card.appendChild(trow);',
  '  }',
  '  if(fArr.length>0){',
  '    card.appendChild(mkEl("div","rc-lbl","偏好口感"));',
  '    var frow2=mkEl("div","ml-stat");',
  '    fArr.slice(0,4).forEach(function(fi){',
  '      var it=mkEl("div","ml-stat-i");',
  '      it.appendChild(mkEl("div","ml-stat-l",fi.label+" ×"+fi.count));',
