  'function showMealScreen(){DIVN={phase:"intro",mood:null,opts:[],picked:[],reasons:[],round:0,allPicked:[]};showScreen("smeal");renderMeal();}',
  'function showReviewScreen(){showScreen("sreview");var sk=document.getElementById("rv-skip-btn");if(sk){sk.onclick=goHome;sk.textContent="略過";}tx("rv-prog","7 日飲食回顧");rvRender({phase:"loading"});rvLoad();}',
  'function rvFetch(method,cb){',
  '  fetch("/api/review",{method:method,headers:method==="POST"?{"Content-Type":"application/json"}:{"Accept":"application/json"},body:method==="POST"?"{}":undefined}).then(function(r){return r.json().then(function(j){cb(r.status,j);},function(){cb(r.status,null);});}).catch(function(){cb(0,null);});',
  '}',
  'function rvLoad(){rvFetch("GET",function(status,j){',
  '  if(status===401){rvRender({phase:"login"});return;}',
  '  if(status===403){rvRender({phase:"locked"});return;}',
  '  if(status===503){rvRender({phase:"unavailable"});return;}',
  '  if(!j||!j.ok){rvRender({phase:"error"});return;}',
  '  rvRender({phase:"ready",data:j.data});',
  '});}',
  'function rvGenerate(){rvRender({phase:"generating"});rvFetch("POST",function(status,j){',
  '  if(status===401){rvRender({phase:"login"});return;}',
  '  if(status===403){rvRender({phase:"locked"});return;}',
  '  if(status===503){rvRender({phase:"unavailable"});return;}',
  '  if(status===429){rvRender({phase:"quota",data:(j&&j.quota)||null});return;}',
  '  if(!j||!j.ok){rvRender({phase:"error"});return;}',
  '  rvRender({phase:"result",data:j.data});',
  '});}',
  'function rvReviewCard(review,isSample){',
  '  var wrap=mkEl("div","res-card");',
  '  if(isSample){var badge=mkEl("div","rv-badge","範例");wrap.appendChild(badge);}',
  '  wrap.appendChild(mkEl("div","rc-lbl","這週實際記錄了什麼"));',
  '  wrap.appendChild(mkEl("div","beh-desc",(review.summary&&review.summary.text)||""));',
  '  if(review.summary&&review.summary.missingNote)wrap.appendChild(mkEl("div","dim-tip",review.summary.missingNote));',
  '  if(review.observation){',
  '    wrap.appendChild(mkEl("div","rc-lbl","一個值得留意的模式"));',
  '    wrap.appendChild(mkEl("div","beh-desc",review.observation.pattern||""));',
  '    if(review.observation.maybe)wrap.appendChild(mkEl("div","dim-tip",review.observation.maybe));',
  '    if(review.observation.uncertain)wrap.appendChild(mkEl("div","dim-tip",review.observation.uncertain));',
  '  }',
  '  if(review.action){',
  '    wrap.appendChild(mkEl("div","rc-lbl","下週一個小行動"));',
  '    wrap.appendChild(mkEl("div","beh-desc",review.action.text||""));',
  '  }',
  '  if(review.dataLimitation)wrap.appendChild(mkEl("div","dim-tip","資料還不夠多，先累積幾天會更貼近你。這是基本摘要，不是個人化解讀。"));',
  '  wrap.appendChild(mkEl("div","dim-tip","這是幫助理解，不是健康診斷或醫療建議。"));',
  '  return wrap;',
  '}',
  'function rvSampleReview(){return {kind:"personalized",dataLimitation:false,summary:{text:"最近 7 天，你在 5 天留下了 9 次記錄。"},observation:{pattern:"這幾天你最常被「炸物」吸引（4 次，約佔記錄的 44%）。",maybe:"可能的解釋之一：這段期間你記錄的壓力平均偏高（約 7／10）。",uncertain:"這只是從少量記錄看到的傾向，不是結論。"},action:{text:"下週可以留意：當你又想吃炸物時，當下的心情和情境是什麼。"}};}',
  'function rvRender(state){',
  '  var body=document.getElementById("rv-body");if(!body)return;body.innerHTML="";body.scrollTop=0;',
  '  if(state.phase==="loading"||state.phase==="generating"){',
  '    body.appendChild(icoDiv("idq-emoji","crystal",46));',
  '    body.appendChild(mkEl("div","idq-intro-sub",state.phase==="generating"?"正在整理你的 7 日回顧…":"載入中…"));',
  '    return;',
  '  }',
  '  if(state.phase==="login"){',
  '    body.appendChild(mkEl("div","idq-intro-title","7 日飲食回顧"));',
  '    body.appendChild(mkEl("div","idq-intro-sub","這是會員功能，需要先登入才能根據你的記錄產生回顧。"));',
  '    var lb=mkEl("button","idq-btn","前往登入");lb.onclick=function(){try{openSyncUI();}catch(e){location.href="/auth/google/start";}};body.appendChild(lb);',
  '    body.appendChild(rvReviewCard(rvSampleReview(),true));',
  '    return;',
  '  }',
  '  if(state.phase==="locked"){',
  '    body.appendChild(mkEl("div","idq-intro-title","7 日飲食回顧 · 會員專屬"));',
  '    body.appendChild(mkEl("div","idq-intro-sub","根據你最近 7 天的記錄，整理出一段實際摘要、一個有依據的觀察、一個可選的小行動。"));',
  '    body.appendChild(mkEl("div","dim-tip","目前為 Premium beta 功能，開放給受邀帳號試用。"));',
  '    body.appendChild(rvReviewCard(rvSampleReview(),true));',
  '    return;',
  '  }',
  '  if(state.phase==="unavailable"){',
  '    body.appendChild(mkEl("div","idq-intro-title","暫時無法確認會員狀態"));',
  '    body.appendChild(mkEl("div","idq-intro-sub","這是暫時的狀況，請稍後再試一次。你的資料與權益都沒有改變。"));',
  '    var rb=mkEl("button","idq-btn sec","重試");rb.onclick=rvLoad;body.appendChild(rb);',
  '    return;',
  '  }',
  '  if(state.phase==="error"){',
  '    body.appendChild(mkEl("div","idq-intro-sub","暫時無法載入回顧，請重試。"));',
  '    var eb=mkEl("button","idq-btn sec","重試");eb.onclick=rvLoad;body.appendChild(eb);',
  '    return;',
  '  }',
  '  if(state.phase==="quota"){',
  '    body.appendChild(mkEl("div","idq-intro-title","本期回顧次數已用完"));',
  '    var q=state.data||{};body.appendChild(mkEl("div","idq-intro-sub","beta 期間每個帳號可產生 "+((q.limit!=null)?q.limit:2)+" 份回顧。已用完的話，等有新記錄的下一期再來。"));',
  '    var qb=mkEl("button","idq-btn sec","看最近一份");qb.onclick=rvLoad;body.appendChild(qb);',
  '    return;',
  '  }',
  '  if(state.phase==="ready"){',
  '    var d=state.data||{};',
  '    body.appendChild(mkEl("div","ml-pick-lbl","7 日飲食回顧"));',
  '    if(d.review){body.appendChild(rvReviewCard(d.review,false));}',
  '    if(d.dataLimitation&&!d.review){body.appendChild(mkEl("div","idq-intro-sub","目前記錄還不夠產生個人化回顧，先多記錄幾天吧。"));}',
  '    if(d.quota){body.appendChild(mkEl("div","dim-tip","本期已用 "+d.quota.used+"／"+d.quota.limit+" 份。"));}',
  '    if(d.canGenerate){var gb=mkEl("button","idq-btn","產生本週回顧");gb.onclick=rvGenerate;body.appendChild(gb);}',
  '    else if(!d.review){var gb2=mkEl("button","idq-btn",d.dataLimitation?"看基本摘要":"產生本週回顧");gb2.onclick=rvGenerate;body.appendChild(gb2);}',
  '    var hb=mkEl("button","idq-btn sec","回首頁");hb.onclick=goHome;body.appendChild(hb);',
  '    return;',
  '  }',
  '  if(state.phase==="result"){',
  '    var dd=state.data||{};',
  '    body.appendChild(mkEl("div","ml-pick-lbl","你的 7 日飲食回顧"));',
  '    if(dd.review)body.appendChild(rvReviewCard(dd.review,false));',
  '    if(dd.quota)body.appendChild(mkEl("div","dim-tip","本期已用 "+dd.quota.used+"／"+dd.quota.limit+" 份。"));',
  '    var hb2=mkEl("button","idq-btn sec","回首頁");hb2.onclick=goHome;body.appendChild(hb2);',
  '    return;',
  '  }',
  '}',
  'function renderMealHomeCard(){',
  '  var el=document.getElementById("mealcard");if(!el)return;',
  '  el.innerHTML="";',
  '  var cta=mkEl("div","idc-cta");cta.onclick=showMealScreen;',
  '  cta.appendChild(mkEl("div","idc-cta-txt","飲食占卜——你現在想吃什麼？"));',
  '  cta.appendChild(mkEl("div","idc-cta-btn","開始占卜"));',
  '  el.appendChild(cta);',
  '}',
  'function showDimInfo(idx){',
