  'function renderNutriSymptoms(c){',
  '  NUTRI_SYMPTOMS.forEach(function(s){',
  '    var card=mkEl("div","nt-card");',
  '    var hdr=mkEl("div","nt-card-hdr");',
  '    hdr.appendChild(mkEl("span","nt-card-emoji",s.emoji));',
  '    var hinfo=mkEl("div","nt-card-hinfo");',
  '    hinfo.appendChild(mkEl("div","nt-card-name",s.name));',
  '    hinfo.appendChild(mkEl("div","nt-card-alias",s.type));',
  '    hdr.appendChild(hinfo);',
  '    card.appendChild(hdr);',
  '    var nSec=mkEl("div","nt-card-sec");',
  '    nSec.appendChild(mkEl("div","nt-card-sec-lbl","關鍵營養素"));',
  '    nSec.appendChild(mkEl("div","nt-card-sec-body",s.nutrients));',
  '    card.appendChild(nSec);',
  '    var pSec=mkEl("div","nt-card-sec nt-tip-sec");',
  '    pSec.appendChild(mkEl("div","nt-card-sec-lbl","飲食方向"));',
  '    pSec.appendChild(mkEl("div","nt-card-sec-body",s.pattern));',
  '    card.appendChild(pSec);',
  '    var rSec=mkEl("div","nt-card-sec nt-warn-sec");',
  '    rSec.appendChild(mkEl("div","nt-card-sec-lbl","何時該就醫"));',
  '    rSec.appendChild(mkEl("div","nt-card-sec-body",s.redflag));',
  '    card.appendChild(rSec);',
  '    var sref=SYM_REF[s.name];',
  '    if(sref){',
  '      var srefSec=mkEl("div","nt-card-sec nt-ref-sec");',
  '      srefSec.appendChild(mkEl("div","nt-card-sec-lbl","實證依據"));',
  '      srefSec.appendChild(mkEl("div","nt-card-sec-body",sref.d));',
  '      srefSec.appendChild(mkEl("div","nt-ref-src-lbl","依據來源"));',
  '      srefSec.appendChild(mkEl("div","nt-ref-src",sref.s));',
  '      card.appendChild(srefSec);',
  '    }',
  '    var sText=" "+s.name+"（"+s.type+"）\\n\\n 關鍵營養素：\\n"+s.nutrients+"\\n\\n 飲食方向：\\n"+s.pattern+"\\n\\n 何時該就醫：\\n"+s.redflag+(sref?"\\n\\n 實證依據："+sref.d+"\\n 依據來源："+sref.s:"")+"\\n\\n 僅供衛教參考，請務必諮詢醫師或營養師。\\n\\n— 飲食行為教練 App";',
  '    addShareBar(card,{text:sText,emoji:s.emoji,title:s.name,sections:[{label:"關鍵營養素"},{text:s.nutrients},{label:"飲食方向"},{text:s.pattern},{label:"何時該就醫"},{text:s.redflag}].concat(sref?[{label:"實證依據"},{text:sref.d},{label:"依據來源"},{text:sref.s}]:[])});',
  '    c.appendChild(card);',
  '  });',
  '}',
  'function renderNutriHomeCard(){',
  '  var el=document.getElementById("nutricard");if(!el)return;',
  '  el.innerHTML="";',
