  '  var seen={};for(var c=0;c<q.length;c++){var ch=q.charAt(c);if(ch>="\\u4e00"&&ch<="\\u9fff"&&!seen[ch]){seen[ch]=1;if(kw.indexOf(ch)!==-1)score+=1;if(s.title.indexOf(ch)!==-1)score+=1;}}',
  '  return score;',
  '}',
  'function scenFind(q){',
  '  q=(q||"").trim();if(!q)return[];',
  '  var arr=SCEN_DATA.map(function(s,i){return {i:i,s:s,score:scenScore(s,q)};});',
  '  arr=arr.filter(function(x){return x.score>0;});',
  '  arr.sort(function(a,b){return b.score-a.score;});',
  '  return arr;',
  '}',
