  'function currentRestore(){',
  '  var a=document.querySelector(".scr.active");var id=a?a.id:"";',
  '  if(id==="sdim"&&DIM_CUR){var k=DIM_CUR.key,dt=DIM_CUR.t;return {id:"sdim",render:function(){populateDim(k);if(dt)showDimDetail(dt);}};}',
  '  if(id==="smove"){var mt=MOVE_CUR&&MOVE_CUR.t;return {id:"smove",render:function(){populateMove();if(mt)showMoveDetail(mt);}};}',
  '  if(id==="sscen"){var st={phase:SCEN.phase,idx:SCEN.idx,choice:SCEN.choice,stopPre:SCEN.stopPre,reflect:SCEN.reflect,query:SCEN.query};return {id:"sscen",render:function(){SCEN=st;renderScen();}};}',
  '  if(id==="snutri"){var c=NUTRI_SEL.cat;return {id:"snutri",render:function(){NUTRI_SEL={cat:c,item:-1};renderNutriTabs();renderNutriList();}};}',
  '  if(id==="smeal"){var dv=JSON.parse(JSON.stringify(DIVN));return {id:"smeal",render:function(){DIVN=dv;renderMeal();}};}',
  '  if(id==="sba"){var bc=JSON.parse(JSON.stringify(BA));return {id:"sba",render:function(){BA=bc;renderBA();}};}',
  '  return null;',
  '}',
