  'function renderOptScen(container,label,sysKey){',
  '  var ids=OPT_SCEN[label];var links=[];',
  '  if(ids&&ids.length){ids.forEach(function(id){var s=scenById(id);if(s)links.push({t:"scen",k:id,label:" "+s.title});});}',
  '  if(!links.length&&DIM_LINKS[sysKey]){DIM_LINKS[sysKey].forEach(function(l){if(l.t==="scen")links.push(l);});}',
  '  if(!links.length)return;',
  '  container.appendChild(mkEl("div","rc-lbl","這個選擇，可以演練的情境"));',
  '  container.appendChild(mkEl("div","ml-hint","把這個選項放進真實的兩難裡練習看看："));',
  '  links.forEach(function(lk){var b=mkEl("button","idq-btn sec",lk.label);(function(x){b.onclick=function(){scenGoLink(x);};})(lk);container.appendChild(b);});',
  '}',
  'function scenGoLink(link){',
  '  if(!link)return;',
  '  navPush(currentRestore());',
  '  if(link.t==="divn"){showMealScreen();return;}',
  '  if(link.t==="scen"){showScenScreen(link.k);return;}',
  '  if(link.t==="sym"){showNutriScreen("symptom");return;}',
  '  if(link.t==="nutri"){showNutriScreen(link.k);return;}',
  '  if(link.t==="dim"){',
  '    if(link.k==="move"){showMove();}else{showDimScreen(link.k);}',
  '    return;',
  '  }',
  '}',
