  'function openCatModal(label){',
  '  var lw=label.toLowerCase();',
  '  var items=SEARCH_DB.filter(function(f){',
  '    var txt=(f.name+" "+f.cat+" "+f.group+" "+f.desc+" "+(f.veg||"")+" "+(f.pro||"")+" "+(f.carb||"")+" "+(f.better||"")).toLowerCase();',
  '    return txt.includes(lw);',
  '  });',
  '  if(!items.length){document.getElementById("srch-inp").value=label;renderSearchResults(label);return;}',
