  '  var body=document.getElementById("sm-body");body.className="sm-body";body.innerHTML="";',
  '  items.forEach(function(f){body.appendChild(buildSearchCard(f,false));});',
  '  body.scrollTop=0;',
  '  document.getElementById("sm").classList.remove("hidden");',
  '}',
