  '  d.ba.entries.unshift({ts:Date.now(),food:BA.food,cat:BA.cat,time:BA.time,situ:BA.situ,why:BA.why,mood:BA.mood,process:BA.process,type:BA.type,redo:BA.redo});',
  '  if(d.ba.entries.length>60)d.ba.entries=d.ba.entries.slice(0,60);sd(d);',
  '}',
