  'function showBAScreen(){BA={phase:"intro",food:"",cat:"",time:"",situ:"",why:"",mood:"",process:"",type:"",redo:"",_saved:false};showScreen("sba");renderBA();}',
  'var BA_CAT_ICON={"正餐":"f_meal","輕食":"f_light","點心甜點":"f_dessert","飲料":"f_drink","宵夜":"f_night","水果":"f_fruit","速食炸物":"f_fried","其他":"f_other"};',
  'function baChipGroup(arr,field){',
  '  var wrap=mkEl("div","ba-chips");',
