  '    chip.appendChild(document.createTextNode(txt));',
  '    (function(val){chip.onclick=function(){BA[field]=(BA[field]===val?"":val);wrap.querySelectorAll(".ba-chip").forEach(function(c){c.classList.remove("sel");});if(BA[field])chip.classList.add("sel");};})(o.v);',
  '    wrap.appendChild(chip);',
  '  });',
  '  return wrap;',
  '}',
  'function baGrid(arr,field,next){',
